// Décodage JSON-stat 2.0 → une observation par ligne.
// Le format encode les valeurs dans un objet plat dont la clé est un index
// multidimensionnel aplati ; il faut le décomposer selon `size` pour retrouver
// la période et la zone. Écrire ce décodage explicitement, plutôt que de
// supposer une dimension unique, évite une erreur silencieuse le jour où le
// filtre géographique s'élargit à plusieurs pays.
// La réponse est lue par référence explicite au nœud d'appel, et non par $input :
// ce nœud est désormais placé APRÈS le dépôt en zone brute, dont il reçoit la sortie.
const resp = $('API Eurostat (sts_inpr_m, NACE C29)').first().json;
const valeurs = resp.value ?? {};
const dims = resp.id ?? [];
const tailles = resp.size ?? [];

const posTemps = dims.indexOf('time');
const posGeo   = dims.indexOf('geo');
if (posTemps < 0) {
  throw new Error('Réponse Eurostat sans dimension temporelle : structure inattendue, collecte interrompue.');
}

function libelles(dimension) {
  const index = resp.dimension?.[dimension]?.category?.index ?? {};
  return Object.keys(index).sort((a, b) => index[a] - index[b]);
}
const periodes = libelles('time');
const zones    = libelles('geo');

// index plat → coordonnées, en base mixte définie par `size`
function coordonnees(plat) {
  const c = new Array(tailles.length);
  for (let d = tailles.length - 1; d >= 0; d--) {
    c[d] = plat % tailles[d];
    plat = Math.floor(plat / tailles[d]);
  }
  return c;
}

const runId  = $('Ouvrir le run').first().json.run_id;
// Référence d'audit : identifiant de run seul. La date est portée par runs.executed_at ;
// la construire ici en UTC alors que le nœud de dépôt la construit en Europe/Zurich
// faisait diverger la référence du fichier réel au passage de minuit.
const rawRef = '/data/staging/A5_eurostat_run' + runId + '.json';

const out = [];
for (const [cle, v] of Object.entries(valeurs)) {
  if (v === null || v === undefined) continue;          // Eurostat laisse des trous : ils restent des trous
  const c = coordonnees(Number(cle));
  const periode = periodes[c[posTemps]];
  const zone    = posGeo >= 0 ? (zones[c[posGeo]] ?? 'EU27_2020') : 'EU27_2020';
  if (!periode) continue;
  out.push({ json: {
    indicator_id: 'A5',
    run_id: runId,
    period: periode,
    geo: zone,
    value: Number(v),
    obtained_by: 'etl',
    validation_status: 'valide_source',
    raw_ref: rawRef
  } });
}

if (out.length === 0) {
  throw new Error('Aucune observation extraite : vérifier les codes de dimension de la requête Eurostat.');
}
out.sort((a, b) => a.json.period.localeCompare(b.json.period));
return out;

// Contrôles qualité déterministes (§ 10.2, couche 3).
// Une valeur qui échoue n'est pas corrigée ni devinée : elle est écartée et comptée.
// Le pipeline ETL n'a pas le droit de produire une valeur qu'il n'a pas lue.
const FENETRE_DEBUT = '2023-01';
const SEUIL_VARIATION_ANORMALE = 50;   // en %, entre deux périodes consécutives

const obs = $input.all().map(i => i.json);
const retenues = [];
const ecartees = [];

let precedente = null;
for (const o of obs) {
  const motifs = [];
  if (!Number.isFinite(o.value))                          motifs.push('valeur non numérique');
  if (!/^\d{4}(-\d{2})?$/.test(o.period))                 motifs.push('format de période invalide');
  if (o.period < FENETRE_DEBUT)                           motifs.push("hors fenêtre d'historique de trois ans");
  if (o.value <= 0)                                       motifs.push('indice nul ou négatif');
  if (precedente && precedente !== 0) {
    const variation = Math.abs((o.value - precedente) / precedente * 100);
    if (variation > SEUIL_VARIATION_ANORMALE)             motifs.push('variation anormale de ' + variation.toFixed(1) + ' %');
  }
  if (motifs.length) { ecartees.push({ ...o, motifs }); }
  else { retenues.push(o); precedente = o.value; }
}

if (retenues.length === 0) {
  throw new Error('Toutes les observations ont été écartées par les contrôles qualité : ' + JSON.stringify(ecartees.slice(0, 3)));
}

// Le bilan de contrôle voyage avec chaque observation : il sera consigné à la clôture du run.
const bilan = { retenues: retenues.length, ecartees: ecartees.length, detail_ecartees: ecartees };
return retenues.map(o => ({ json: { ...o, _bilan: bilan } }));
